import XCTest

final class ReorderUITest: XCTestCase {

    func printFrames(_ app: XCUIApplication, tag: String) {
        NSLog("FRAMES-\(tag)-BEGIN")
        for name in ["くるま", "電車", "新幹線", "飛行機", "歩き"] {
            let b = app.buttons[name]
            if b.exists {
                let f = b.frame
                NSLog("FRAME \(tag) \(name) x=%.0f y=%.0f", f.minX, f.minY)
            } else {
                NSLog("FRAME \(tag) \(name) MISSING")
            }
        }
        NSLog("FRAMES-\(tag)-END")
    }

    func testLiveReorderDuringDrag() throws {
        let app = XCUIApplication(bundleIdentifier: "me.teraoka.Picton")
        app.launch()

        // 「手段」カテゴリへ切り替え
        let categoryButton = app.buttons["手段カテゴリ"]
        XCTAssertTrue(categoryButton.waitForExistence(timeout: 15), "手段カテゴリボタンが見つからない")
        categoryButton.tap()
        sleep(1)

        // 編集モードに入る
        let editButton = app.buttons["編集モード"]
        XCTAssertTrue(editButton.waitForExistence(timeout: 5), "編集ボタンが見つからない")
        editButton.tap()
        sleep(1)

        let kuruma = app.buttons["くるま"]
        let hikouki = app.buttons["飛行機"]
        XCTAssertTrue(kuruma.waitForExistence(timeout: 5), "くるまカードが見つからない")
        XCTAssertTrue(hikouki.exists, "飛行機カードが見つからない")

        printFrames(app, tag: "BEFORE")
        let hikoukiFrameBefore = hikouki.frame
        let kurumaFrameBefore = kuruma.frame

        // くるまを長押しして飛行機の位置までドラッグし、指を離す前に3秒ホールド
        NSLog("DRAG-START")
        let start = kuruma.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
        let end = hikouki.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
        start.press(forDuration: 1.5, thenDragTo: end, withVelocity: .slow, thenHoldForDuration: 3.0)
        NSLog("DRAG-END")

        sleep(2)
        printFrames(app, tag: "AFTER")

        // くるまが飛行機の元の位置(2行目左端)へ移動していること
        let kurumaFrameAfter = app.buttons["くるま"].frame
        XCTAssertEqual(kurumaFrameAfter.minX, hikoukiFrameBefore.minX, accuracy: 20, "くるまのX座標が飛行機の元位置と一致しない")
        XCTAssertEqual(kurumaFrameAfter.minY, hikoukiFrameBefore.minY, accuracy: 20, "くるまのY座標が飛行機の元位置と一致しない")
        // 電車が先頭(くるまの元の位置)へ繰り上がっていること
        let denshaFrameAfter = app.buttons["電車"].frame
        XCTAssertEqual(denshaFrameAfter.minX, kurumaFrameBefore.minX, accuracy: 20, "電車が先頭に繰り上がっていない")
        XCTAssertEqual(denshaFrameAfter.minY, kurumaFrameBefore.minY, accuracy: 20, "電車が先頭に繰り上がっていない")

        // 再起動して順序が永続化されているか確認
        app.terminate()
        app.launch()
        let cat2 = app.buttons["手段カテゴリ"]
        XCTAssertTrue(cat2.waitForExistence(timeout: 15))
        cat2.tap()
        sleep(1)
        printFrames(app, tag: "RELAUNCH")
        let kurumaRelaunch = app.buttons["くるま"].frame
        XCTAssertEqual(kurumaRelaunch.minX, hikoukiFrameBefore.minX, accuracy: 20, "再起動後にくるまの位置が保持されていない")
        XCTAssertEqual(kurumaRelaunch.minY, hikoukiFrameBefore.minY, accuracy: 20, "再起動後にくるまの位置が保持されていない")
    }
}

import XCTest

final class ReorderUITest: XCTestCase {

    func printFrames(_ app: XCUIApplication, tag: String) {
        NSLog("FRAMES-\(tag)-BEGIN")
        for name in ["くるま", "電車", "新幹線", "飛行機", "歩き"] {
            let b = app.buttons[name]
            if b.exists {
                let f = b.frame
                NSLog("FRAME \(tag) \(name) x=%.0f y=%.0f", f.minX, f.minY)
            } else {
                NSLog("FRAME \(tag) \(name) MISSING")
            }
        }
        NSLog("FRAMES-\(tag)-END")
    }

    func testLiveReorderDuringDrag() throws {
        let app = XCUIApplication(bundleIdentifier: "me.teraoka.Picton")
        app.launch()

        // 「手段」カテゴリへ切り替え
        let categoryButton = app.buttons["手段カテゴリ"]
        XCTAssertTrue(categoryButton.waitForExistence(timeout: 15), "手段カテゴリボタンが見つからない")
        categoryButton.tap()
        sleep(1)

        // 編集モードに入る
        let editButton = app.buttons["編集モード"]
        XCTAssertTrue(editButton.waitForExistence(timeout: 5), "編集ボタンが見つからない")
        editButton.tap()
        sleep(1)

        let kuruma = app.buttons["くるま"]
        let hikouki = app.buttons["飛行機"]
        XCTAssertTrue(kuruma.waitForExistence(timeout: 5), "くるまカードが見つからない")
        XCTAssertTrue(hikouki.exists, "飛行機カードが見つからない")

        printFrames(app, tag: "BEFORE")
        let hikoukiFrameBefore = hikouki.frame
        let kurumaFrameBefore = kuruma.frame

        // ドラッグ中(指を離す前)の状態をバックグラウンドスレッドから観測する
        // ジェスチャ: 1.5秒長押し → slowドラッグ → 到達後3秒ホールド → リリース
        // ドラッグ移動完了は開始から2.5〜3秒後、リリースは6秒前後の見込み
        let shotLock = NSLock()
        var midDragShots: [(String, Data)] = []
        for delay in [3.5, 4.5, 5.2] {
            DispatchQueue.global().asyncAfter(deadline: .now() + delay) {
                let png = XCUIScreen.main.screenshot().pngRepresentation
                shotLock.lock()
                midDragShots.append((String(format: "middrag_t%.1f", delay), png))
                shotLock.unlock()
                NSLog("MIDDRAG-SHOT t=%.1f bytes=%d", delay, png.count)
            }
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + 4.0) {
            NSLog("MIDFRAMES-BEGIN (during hold, before release)")
            for name in ["電車", "新幹線", "飛行機", "歩き", "くるま"] {
                let b = app.buttons[name]
                if b.exists {
                    let f = b.frame
                    NSLog("MIDFRAME \(name) x=%.0f y=%.0f", f.minX, f.minY)
                } else {
                    NSLog("MIDFRAME \(name) MISSING")
                }
            }
            NSLog("MIDFRAMES-END")
        }

        NSLog("DRAG-START")
        let start = kuruma.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
        let end = hikouki.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
        start.press(forDuration: 1.5, thenDragTo: end, withVelocity: .slow, thenHoldForDuration: 3.0)
        NSLog("DRAG-END")

        sleep(2)
        printFrames(app, tag: "AFTER")

        // ミッドドラッグのスクリーンショットを xcresult に保存
        shotLock.lock()
        for (name, data) in midDragShots {
            let attachment = XCTAttachment(data: data, uniformTypeIdentifier: "public.png")
            attachment.name = name
            attachment.lifetime = .keepAlways
            add(attachment)
        }
        shotLock.unlock()
        let afterShot = XCTAttachment(data: XCUIScreen.main.screenshot().pngRepresentation, uniformTypeIdentifier: "public.png")
        afterShot.name = "after_drop"
        afterShot.lifetime = .keepAlways
        add(afterShot)

        // くるまが飛行機の元の位置(2行目左端)へ移動していること
        let kurumaFrameAfter = app.buttons["くるま"].frame
