3	enum ImageStorageService {
4	    static func save(image: UIImage, id: UUID) throws -> URL {
5	        let directory = Constants.customImageDirectory
6	        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
7	
8	        let size = CGSize(width: Constants.cardImageSize, height: Constants.cardImageSize)
9	        let renderer = UIGraphicsImageRenderer(size: size)
10	        let resized = renderer.image { _ in
11	            image.draw(in: CGRect(origin: .zero, size: size))
12	        }
13	
14	        guard let data = resized.jpegData(compressionQuality: Constants.cardImageCompressionQuality) else {
15	            throw ImageStorageError.compressionFailed
16	        }
17	
18	        let fileURL = directory.appendingPathComponent("\(id.uuidString).jpg")
19	        try data.write(to: fileURL)
20	        return fileURL
21	    }
22	
23	    static func load(id: UUID) -> UIImage? {
24	        let fileURL = Constants.customImageDirectory.appendingPathComponent("\(id.uuidString).jpg")
25	        guard let data = try? Data(contentsOf: fileURL) else { return nil }
26	        return UIImage(data: data)
27	    }
28	
29	    static func delete(id: UUID) {
30	        let fileURL = Constants.customImageDirectory.appendingPathComponent("\(id.uuidString).jpg")
31	        try? FileManager.default.removeItem(at: fileURL)
32	    }
33	}
