4	enum PresetImageBootstrapper {
5	    /// 削除対象のプリセット画像名
6	    private static let removedPresetImageNames: Set<String> = [
7	        "preset_shibuya", "preset_kitasenju", "preset_mitsukoshimae",
8	        "preset_mcdonalds", "preset_saizeriya", "preset_gusto",
