11	        "preset_ramen", "preset_ringo", "preset_udon",
12	        "preset_natto", "preset_kakipea", "preset_cola",
13	    ]
14	
15	    static func bootstrapIfNeeded(context: ModelContext) {
16	        let descriptor = FetchDescriptor<PictureCard>(
17	            predicate: #Predicate { $0.isPreset == true }
18	        )
19	        let existingCount = (try? context.fetchCount(descriptor)) ?? 0
20	
21	        if existingCount == 0 {
22	            for (index, definition) in PresetCardData.all.enumerated() {
23	                let card = PictureCard(
24	                    displayName: definition.displayName,
25	                    kanaText: definition.kanaText,
26	                    category: definition.category,
27	                    isPreset: true,
28	                    presetImageName: definition.sfSymbol,
29	                    sortOrder: index
30	                )
31	                context.insert(card)
32	            }
33	        } else {
34	            removeDeletedPresets(context: context)
35	            addNewPresets(context: context)
36	        }
37	
38	        try? context.save()
39	    }
40	
41	    /// PresetCardData に追加された新規プリセットカードを DB に挿入する
42	    private static func addNewPresets(context: ModelContext) {
43	        let descriptor = FetchDescriptor<PictureCard>(
44	            predicate: #Predicate { $0.isPreset == true }
45	        )
46	        guard let existing = try? context.fetch(descriptor) else { return }
47	        let existingSymbols = Set(existing.compactMap { $0.presetImageName })
48	        let maxSortOrder = existing.map { $0.sortOrder }.max() ?? -1
49	
50	        let newDefinitions = PresetCardData.all.filter { !existingSymbols.contains($0.sfSymbol) }
51	        for (offset, definition) in newDefinitions.enumerated() {
52	            let card = PictureCard(
53	                displayName: definition.displayName,
54	                kanaText: definition.kanaText,
55	                category: definition.category,
56	                isPreset: true,
57	                presetImageName: definition.sfSymbol,
58	                sortOrder: maxSortOrder + 1 + offset
59	            )
60	            context.insert(card)
61	        }
62	    }
63	
64	    /// PresetCardData から削除されたプリセットカードを DB からも除去する
65	    private static func removeDeletedPresets(context: ModelContext) {
66	        let descriptor = FetchDescriptor<PictureCard>(
67	            predicate: #Predicate { $0.isPreset == true }
68	        )
69	        guard let presets = try? context.fetch(descriptor) else { return }
70	        for card in presets {
71	            if let imageName = card.presetImageName,
72	               removedPresetImageNames.contains(imageName) {
73	                context.delete(card)
74	            }
75	        }
76	    }
77	}
