144	    private func cardForSelectedDate(_ date: Date) -> PictureCard {
145	        let d = Calendar.current.startOfDay(for: date)
146	        if d == today {
147	            return PictureCard(displayName: "きょう", kanaText: "きょう", category: "いつ",
148	                               isPreset: true, presetImageName: "sun.max.fill")
149	        } else if d == tomorrow {
150	            return PictureCard(displayName: "あした", kanaText: "あした", category: "いつ",
151	                               isPreset: true, presetImageName: "moon.stars.fill")
152	        } else if d == dayAfterTomorrow {
153	            return PictureCard(displayName: "あさって", kanaText: "あさって", category: "いつ",
154	                               isPreset: true, presetImageName: "calendar.badge.plus")
155	        }
156	        return makeDateCard(for: date)
157	    }
