159	    private func makeDateCard(for date: Date) -> PictureCard {
160	        let cal = Calendar.current
161	        let month = cal.component(.month, from: date)
162	        let day = cal.component(.day, from: date)
163	        return PictureCard(
164	            displayName: "\(month)月\(day)日",
165	            kanaText: dateKana(month: month, day: day),
166	            category: "いつ",
167	            isPreset: true,
168	            presetImageName: "calendar"
169	        )
170	    }
