172	    private func dateKana(month: Int, day: Int) -> String {
173	        "\(monthReading(month)) \(dayReading(day))"
174	    }
175	
176	    private func monthReading(_ month: Int) -> String {
177	        let readings = [
178	            "", "いちがつ", "にがつ", "さんがつ", "しがつ", "ごがつ", "ろくがつ",
179	            "しちがつ", "はちがつ", "くがつ", "じゅうがつ", "じゅういちがつ", "じゅうにがつ"
180	        ]
181	        return month >= 1 && month <= 12 ? readings[month] : "\(month)がつ"
182	    }
183	
184	    private func dayReading(_ day: Int) -> String {
185	        let special: [Int: String] = [
186	            1: "ついたち", 2: "ふつか", 3: "みっか", 4: "よっか", 5: "いつか",
187	            6: "むいか", 7: "なのか", 8: "ようか", 9: "ここのか", 10: "とおか",
188	            14: "じゅうよっか", 20: "はつか", 24: "にじゅうよっか"
189	        ]
190	        if let s = special[day] { return s }
191	        return numberKana(day) + "にち"
192	    }
193	
194	    private func numberKana(_ n: Int) -> String {
195	        let units = ["", "いち", "に", "さん", "し", "ご", "ろく", "しち", "はち", "く"]
196	        if n <= 9 { return units[n] }
197	        if n == 10 { return "じゅう" }
198	        let tens = n / 10
199	        let ones = n % 10
200	        let tensStr = tens == 1 ? "じゅう" : units[tens] + "じゅう"
201	        return tensStr + (ones > 0 ? units[ones] : "")
202	    }
203	}
