307	    private func calendarDays(for month: Date) -> [Date?] {
308	        let comps = cal.dateComponents([.year, .month], from: month)
309	        guard let startOfMonth = cal.date(from: comps),
310	              let range = cal.range(of: .day, in: .month, for: startOfMonth) else { return [] }
311	
312	        let firstWeekday = cal.component(.weekday, from: startOfMonth)  // 1=日, ..., 7=土
313	        let offset = firstWeekday - 1
314	
315	        var days: [Date?] = Array(repeating: nil, count: offset)
316	        for day in 0..<range.count {
317	            days.append(cal.date(byAdding: .day, value: day, to: startOfMonth))
318	        }
319	        while days.count % 7 != 0 { days.append(nil) }
320	        return days
321	    }
