372	// MARK: - 日本の祝日計算
373	
374	private struct JapaneseHolidayChecker {
375	
376	    private let cal: Calendar = {
377	        var c = Calendar(identifier: .gregorian)
378	        c.locale = Locale(identifier: "ja_JP")
379	        c.firstWeekday = 1
380	        return c
381	    }()
382	
383	    func isHoliday(_ date: Date) -> Bool {
384	        isBaseHoliday(date) || isSubstituteHoliday(date) || isCitizensHoliday(date)
385	    }
386	
387	    // 基本祝日
388	    private func isBaseHoliday(_ date: Date) -> Bool {
389	        baseHolidayName(for: date) != nil
390	    }
391	
392	    private func baseHolidayName(for date: Date) -> String? {
393	        let comps = cal.dateComponents([.year, .month, .day, .weekday], from: date)
394	        guard let year = comps.year, let month = comps.month,
395	              let day = comps.day, let weekday = comps.weekday else { return nil }
396	
397	        switch month {
398	        case 1:
399	            if day == 1 { return "元日" }
400	            if weekday == 2, (8...14).contains(day) { return "成人の日" }      // 第2月曜
401	        case 2:
402	            if day == 11 { return "建国記念の日" }
403	            if day == 23, year >= 2020 { return "天皇誕生日" }
404	        case 3:
405	            if day == springEquinox(year: year) { return "春分の日" }
406	        case 4:
407	            if day == 29 { return "昭和の日" }
408	        case 5:
409	            if day == 3 { return "憲法記念日" }
410	            if day == 4 { return "みどりの日" }
411	            if day == 5 { return "こどもの日" }
412	        case 7:
413	            if weekday == 2, (15...21).contains(day) { return "海の日" }       // 第3月曜
414	        case 8:
415	            if day == 11 { return "山の日" }
416	        case 9:
417	            if weekday == 2, (15...21).contains(day) { return "敬老の日" }     // 第3月曜
418	            if day == autumnEquinox(year: year) { return "秋分の日" }
419	        case 10:
420	            if weekday == 2, (8...14).contains(day) { return "スポーツの日" }  // 第2月曜
421	        case 11:
422	            if day == 3 { return "文化の日" }
423	            if day == 23 { return "勤労感謝の日" }
424	        default:
425	            break
426	        }
427	        return nil
428	    }
429	
430	    // 振替休日: 基本祝日が日曜→翌日以降で連続する基本祝日をスキップした最初の平日
431	    private func isSubstituteHoliday(_ date: Date) -> Bool {
432	        let weekday = cal.component(.weekday, from: date)
433	        guard weekday != 1, !isBaseHoliday(date) else { return false }
434	
435	        // 前日から遡り、連続する基本祝日の先頭が日曜かを確認
436	        var cursor = date
437	        while let prev = cal.date(byAdding: .day, value: -1, to: cursor) {
438	            let prevWeekday = cal.component(.weekday, from: prev)
439	            if prevWeekday == 1 {
440	                return isBaseHoliday(prev)
441	            }
442	            if isBaseHoliday(prev) {
443	                cursor = prev
444	            } else {
445	                break
446	            }
447	        }
448	        return false
449	    }
450	
451	    // 国民の休日: 前日・翌日がともに基本祝日に挟まれた平日
452	    private func isCitizensHoliday(_ date: Date) -> Bool {
453	        guard !isBaseHoliday(date) else { return false }
454	        let weekday = cal.component(.weekday, from: date)
455	        guard weekday != 1 else { return false }
456	        guard let prev = cal.date(byAdding: .day, value: -1, to: date),
457	              let next = cal.date(byAdding: .day, value: 1, to: date) else { return false }
458	        return isBaseHoliday(prev) && isBaseHoliday(next)
459	    }
460	
461	    // 春分の日（1980〜2099年）
462	    private func springEquinox(year: Int) -> Int {
463	        Int(20.8431 + 0.242194 * Double(year - 1980) - Double((year - 1980) / 4))
464	    }
465	
466	    // 秋分の日（1980〜2099年）
467	    private func autumnEquinox(year: Int) -> Int {
468	        Int(23.2488 + 0.242194 * Double(year - 1980) - Double((year - 1980) / 4))
469	    }
470	}
